package com.placement;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.http.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import java.io.*;import java.nio.file.*;import java.time.*;import java.math.BigDecimal;import java.util.*;

@RestController @RequestMapping("/api") class ApiController {
 private final UserRepository users; private final ProfileRepository profiles; private final JobRepository jobs; private final ApplicationRepository applications; private final SettingsRepository settings; private final NotificationRepository notifications;
 private final PasswordEncoder encoder; private final TokenService tokens; private final ResumeStorage storage;
 ApiController(UserRepository u,ProfileRepository p,JobRepository j,ApplicationRepository a,SettingsRepository s,NotificationRepository n,PasswordEncoder e,TokenService t,ResumeStorage storage){users=u;profiles=p;jobs=j;applications=a;settings=s;notifications=n;encoder=e;tokens=t;this.storage=storage;}
 record Register(@NotBlank @Size(max=120) String fullName,@Email @NotBlank String email,@NotBlank @Size(min=8,max=72) String password){}
 record Login(@Email @NotBlank String email,@NotBlank String password){}
 record JobInput(@NotBlank String companyName,@NotBlank String title,String location,String employmentType,String salary,String description,String responsibilities,String qualifications,String skills,BigDecimal minCgpa,String departments,LocalDate deadline,String selectionProcess,String additionalRequirements){}
 @Bean ApplicationRunner seedAdmin(@Value("${app.admin-email:}") String email,@Value("${app.admin-password:}") String password){return args->{if(!email.isBlank()&&!password.isBlank())users.findByEmail(email.toLowerCase()).orElseGet(()->{var x=new UserEntity();x.fullName="Placement Administrator";x.email=email.toLowerCase();x.passwordHash=encoder.encode(password);x.role="ADMIN";return users.save(x);});};}
 private UserEntity current(org.springframework.security.core.Authentication auth){if(auth==null||auth.getName()==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return users.findByEmail(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private Map<String,Object> userView(UserEntity u){return Map.of("id",u.id,"fullName",u.fullName,"email",u.email,"role",u.role);}
 @PostMapping("/auth/register") ResponseEntity<?> register(@Valid @RequestBody Register r){String email=r.email().trim().toLowerCase();if(users.findByEmail(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");var u=new UserEntity();u.fullName=r.fullName().trim();u.email=email;u.passwordHash=encoder.encode(r.password());u.role="STUDENT";u=users.save(u);var p=new StudentProfile();p.user=u;profiles.save(p);var set=new UserSettings();set.userId=u.id;settings.save(set);return ResponseEntity.status(201).body(Map.of("token",tokens.issue(u),"user",userView(u)));}
 @PostMapping("/auth/login") Map<String,Object> login(@Valid @RequestBody Login r){var u=users.findByEmail(r.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(r.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return Map.of("token",tokens.issue(u),"user",userView(u));}
 @GetMapping("/auth/me") Map<String,Object> me(org.springframework.security.core.Authentication a){return userView(current(a));}
 @GetMapping("/jobs") Map<String,Object> listJobs(@RequestParam(required=false) String q,@RequestParam(required=false) String location,@RequestParam(required=false) String type,@RequestParam(required=false) String department,@RequestParam(required=false) String skill,@RequestParam(defaultValue="newest") String sort,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="12") int size){var list=new ArrayList<>(jobs.findByStatusOrderByPublishedAtDesc("PUBLISHED"));list.removeIf(j->j.deadline!=null&&j.deadline.isBefore(LocalDate.now()));if(q!=null&&!q.isBlank())list.removeIf(j->!((j.title+" "+j.companyName).toLowerCase().contains(q.toLowerCase())));if(location!=null&&!location.isBlank())list.removeIf(j->j.location==null||!j.location.toLowerCase().contains(location.toLowerCase()));if(type!=null&&!type.isBlank())list.removeIf(j->j.employmentType==null||!j.employmentType.equalsIgnoreCase(type));if(department!=null&&!department.isBlank())list.removeIf(j->j.departments!=null&&!j.departments.toLowerCase().contains(department.toLowerCase()));if(skill!=null&&!skill.isBlank())list.removeIf(j->j.skills==null||!j.skills.toLowerCase().contains(skill.toLowerCase()));if(sort.equals("deadline"))list.sort(Comparator.comparing(j->j.deadline,Comparator.nullsLast(Comparator.naturalOrder())));int safeSize=Math.max(1,Math.min(size,50)),total=list.size(),pages=(int)Math.ceil((double)total/safeSize),safePage=Math.max(0,page),from=Math.min(safePage*safeSize,total),to=Math.min(from+safeSize,total);return Map.of("items",list.subList(from,to),"page",safePage,"size",safeSize,"totalPages",pages,"totalElements",total);}
 @GetMapping("/jobs/{id}") Job job(@PathVariable Long id){var j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!j.status.equals("PUBLISHED")||(j.deadline!=null&&j.deadline.isBefore(LocalDate.now())))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return j;}
 @GetMapping("/profile/me") Map<String,Object> profile(org.springframework.security.core.Authentication a){var u=current(a);var p=profiles.findByUserId(u.id).orElseThrow();var out=new LinkedHashMap<String,Object>();out.put("id",u.id);out.put("fullName",u.fullName);out.put("email",u.email);out.put("phone",p.phone);out.put("dateOfBirth",p.dateOfBirth);out.put("gender",p.gender);out.put("address",p.address);out.put("city",p.city);out.put("state",p.state);out.put("college",p.college);out.put("department",p.department);out.put("degree",p.degree);out.put("specialization",p.specialization);out.put("semester",p.semester);out.put("graduationYear",p.graduationYear);out.put("cgpa",p.cgpa);out.put("backlogs",p.backlogs);out.put("skills",p.skills);out.put("programmingLanguages",p.programmingLanguages);out.put("certifications",p.certifications);out.put("projects",p.projects);out.put("internships",p.internships);out.put("workExperience",p.workExperience);out.put("linkedinUrl",p.linkedinUrl);out.put("githubUrl",p.githubUrl);out.put("portfolioUrl",p.portfolioUrl);out.put("resumeFilename",p.resumeFilename);out.put("resumeUploadedAt",p.resumeUploadedAt);out.put("completion",completion(p));return out;}
 private int completion(StudentProfile p){int n=0;Object[] values={p.phone,p.college,p.department,p.degree,p.graduationYear,p.cgpa,p.skills,p.resumeFilename};for(Object x:values)if(x!=null&&!x.toString().isBlank())n++;return n*100/8;}
 @PutMapping("/profile/me") Map<String,Object> updateProfile(org.springframework.security.core.Authentication a,@RequestBody Map<String,Object> b){var u=current(a);var p=profiles.findByUserId(u.id).orElseThrow();if(b.containsKey("fullName")){String name=Objects.toString(b.get("fullName"),"").trim();if(name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Full name is required");u.fullName=name;users.save(u);}assign(b,"phone",v->p.phone=v);assign(b,"gender",v->p.gender=v);assign(b,"address",v->p.address=v);assign(b,"city",v->p.city=v);assign(b,"state",v->p.state=v);assign(b,"college",v->p.college=v);assign(b,"department",v->p.department=v);assign(b,"degree",v->p.degree=v);assign(b,"specialization",v->p.specialization=v);assign(b,"skills",v->p.skills=v);assign(b,"programmingLanguages",v->p.programmingLanguages=v);assign(b,"certifications",v->p.certifications=v);assign(b,"projects",v->p.projects=v);assign(b,"internships",v->p.internships=v);assign(b,"workExperience",v->p.workExperience=v);assign(b,"linkedinUrl",v->p.linkedinUrl=v);assign(b,"githubUrl",v->p.githubUrl=v);assign(b,"portfolioUrl",v->p.portfolioUrl=v);try{if(b.containsKey("dateOfBirth"))p.dateOfBirth=date(b.get("dateOfBirth"));if(b.containsKey("semester"))p.semester=integer(b.get("semester"));if(b.containsKey("graduationYear"))p.graduationYear=integer(b.get("graduationYear"));if(b.containsKey("backlogs"))p.backlogs=integer(b.get("backlogs"));if(b.containsKey("cgpa"))p.cgpa=decimal(b.get("cgpa"));}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid academic or date value");}profiles.save(p);return profile(a);}
 private interface Setter{void set(String v);} private void assign(Map<String,Object>b,String k,Setter s){if(b.containsKey(k))s.set(b.get(k)==null?null:Objects.toString(b.get(k)));}private Integer integer(Object o){return o==null||o.toString().isBlank()?null:Integer.valueOf(o.toString());}private BigDecimal decimal(Object o){return o==null||o.toString().isBlank()?null:new BigDecimal(o.toString());}private LocalDate date(Object o){return o==null||o.toString().isBlank()?null:LocalDate.parse(o.toString());}
 @PostMapping(value="/resume",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) Map<String,Object> uploadResume(org.springframework.security.core.Authentication a,@RequestPart("file") MultipartFile file)throws IOException{if(file.isEmpty()||file.getSize()>5*1024*1024||!MediaType.APPLICATION_PDF_VALUE.equalsIgnoreCase(file.getContentType()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload a PDF up to 5 MB");byte[] head=file.getBytes();if(head.length<4||head[0]!='%'||head[1]!='P'||head[2]!='D'||head[3]!='F')throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The uploaded file is not a valid PDF");var u=current(a);var p=profiles.findByUserId(u.id).orElseThrow();String previous=p.resumePath;String key=storage.store(u.id,head);p.resumePath=key;p.resumeFilename=Path.of(Objects.requireNonNullElse(file.getOriginalFilename(),"resume.pdf")).getFileName().toString();p.resumeUploadedAt=LocalDateTime.now();profiles.save(p);if(previous!=null&&!previous.equals(key))storage.delete(previous);return Map.of("filename",p.resumeFilename,"uploadedAt",p.resumeUploadedAt);}
 @GetMapping("/resume") ResponseEntity<byte[]> downloadResume(org.springframework.security.core.Authentication a){var u=current(a);var p=profiles.findByUserId(u.id).orElseThrow();return resumeResponse(p);}
 private ResponseEntity<byte[]> resumeResponse(StudentProfile p){try{if(p.resumePath==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"No resume uploaded");byte[] data=storage.read(p.resumePath);return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+p.resumeFilename.replace("\"","")+"\"").body(data);}catch(IOException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Resume file unavailable");}}
 @DeleteMapping("/resume") ResponseEntity<?> deleteResume(org.springframework.security.core.Authentication a)throws IOException{var p=profiles.findByUserId(current(a).id).orElseThrow();if(p.resumePath!=null)storage.delete(p.resumePath);p.resumePath=null;p.resumeFilename=null;p.resumeUploadedAt=null;profiles.save(p);return ResponseEntity.noContent().build();}
 @PostMapping("/applications/jobs/{jobId}") ResponseEntity<?> apply(@PathVariable Long jobId,org.springframework.security.core.Authentication a){var u=current(a);var job=jobs.findById(jobId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Job not found"));if(!job.status.equals("PUBLISHED")||(job.deadline!=null&&job.deadline.isBefore(LocalDate.now())))throw new ResponseStatusException(HttpStatus.CONFLICT,"This job is no longer accepting applications");var p=profiles.findByUserId(u.id).orElseThrow();if(p.resumePath==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Upload a resume before applying");if(job.minCgpa!=null&&(p.cgpa==null||p.cgpa.compareTo(job.minCgpa)<0))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not meet the minimum CGPA requirement");if(job.departments!=null&&!job.departments.isBlank()&&(p.department==null||!job.departments.toLowerCase().contains(p.department.toLowerCase())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Your department is not eligible for this role");if(applications.existsByStudentIdAndJobId(u.id,jobId))throw new ResponseStatusException(HttpStatus.CONFLICT,"You have already applied for this job");var x=new ApplicationEntity();x.student=u;x.job=job;applications.save(x);var prefs=settings.findById(u.id).orElse(null);if(prefs==null||prefs.applicationUpdates){var n=new NotificationEntity();n.userId=u.id;n.title="Application received";n.message="Your application for "+job.title+" at "+job.companyName+" was submitted.";notifications.save(n);}return ResponseEntity.status(201).body(Map.of("message","Application submitted","id",x.id));}
 @GetMapping("/applications/me") List<?> myApplications(org.springframework.security.core.Authentication a){return applications.findByStudentIdOrderByAppliedAtDesc(current(a).id).stream().map(this::applicationView).toList();}
 @GetMapping("/applications/me/{id}") Map<String,Object> myApplication(@PathVariable Long id,org.springframework.security.core.Authentication a){var x=applications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!x.student.id.equals(current(a).id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return applicationView(x);}
 @PatchMapping("/applications/{id}/withdraw") Map<String,Object> withdraw(@PathVariable Long id,org.springframework.security.core.Authentication a){var x=applications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!x.student.id.equals(current(a).id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);if(!List.of("APPLIED","UNDER_REVIEW").contains(x.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This application can no longer be withdrawn");x.status="WITHDRAWN";return applicationView(applications.save(x));}
 private Map<String,Object> applicationView(ApplicationEntity x){var result=new LinkedHashMap<String,Object>();result.put("id",x.id);result.put("status",x.status);result.put("appliedAt",x.appliedAt);result.put("job",x.job);result.put("student",Map.of("id",x.student.id,"fullName",x.student.fullName,"email",x.student.email));return result;}
 @GetMapping("/dashboard/me") Map<String,Object> dashboard(org.springframework.security.core.Authentication a){var u=current(a);var apps=applications.findByStudentIdOrderByAppliedAtDesc(u.id);var p=profiles.findByUserId(u.id).orElseThrow();return Map.of("name",u.fullName,"profileCompletion",completion(p),"hasResume",p.resumePath!=null,"availableJobs",jobs.findByStatusOrderByPublishedAtDesc("PUBLISHED").size(),"applications",apps.size(),"shortlisted",apps.stream().filter(x->x.status.equals("SHORTLISTED")).count(),"selected",apps.stream().filter(x->x.status.equals("SELECTED")).count(),"recentApplications",apps.stream().limit(5).map(this::applicationView).toList(),"recentJobs",jobs.findByStatusOrderByPublishedAtDesc("PUBLISHED").stream().limit(5).toList());}
 @GetMapping("/settings") Map<String,Object> getSettings(org.springframework.security.core.Authentication a){var u=current(a);var s=settings.findById(u.id).orElseGet(()->{var x=new UserSettings();x.userId=u.id;return settings.save(x);});return Map.of("emailNotifications",s.emailNotifications,"applicationUpdates",s.applicationUpdates);}
 @PutMapping("/settings") Map<String,Object> putSettings(org.springframework.security.core.Authentication a,@RequestBody Map<String,Boolean>b){var u=current(a);var s=settings.findById(u.id).orElseGet(()->{var x=new UserSettings();x.userId=u.id;return x;});if(b.containsKey("emailNotifications"))s.emailNotifications=Boolean.TRUE.equals(b.get("emailNotifications"));if(b.containsKey("applicationUpdates"))s.applicationUpdates=Boolean.TRUE.equals(b.get("applicationUpdates"));settings.save(s);return Map.of("emailNotifications",s.emailNotifications,"applicationUpdates",s.applicationUpdates);}
 @PatchMapping("/settings/password") ResponseEntity<?> changePassword(org.springframework.security.core.Authentication a,@RequestBody Map<String,String>b){var u=current(a);String old=b.getOrDefault("currentPassword","");String next=b.getOrDefault("newPassword","");if(!encoder.matches(old,u.passwordHash))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect");if(next.length()<8||next.length()>72)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"New password must be 8 to 72 characters");u.passwordHash=encoder.encode(next);users.save(u);return ResponseEntity.noContent().build();}
 @GetMapping("/notifications") List<?> myNotifications(org.springframework.security.core.Authentication a){return notifications.findByUserIdOrderByCreatedAtDesc(current(a).id).stream().map(n->Map.of("id",n.id,"title",n.title,"message",n.message,"createdAt",n.createdAt==null?LocalDateTime.now():n.createdAt,"read",n.readAt!=null)).toList();}
 @PatchMapping("/notifications/{id}/read") ResponseEntity<?> readNotification(@PathVariable Long id,org.springframework.security.core.Authentication a){var n=notifications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!n.userId.equals(current(a).id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);n.readAt=LocalDateTime.now();notifications.save(n);return ResponseEntity.noContent().build();}
 @GetMapping("/public/stats") Map<String,Object> stats(){return Map.of("students",users.count()-users.findAll().stream().filter(x->x.role.equals("ADMIN")).count(),"jobs",jobs.findByStatusOrderByPublishedAtDesc("PUBLISHED").size(),"applications",applications.count(),"placements",applications.countByStatus("SELECTED"));}
 @GetMapping("/admin/dashboard") Map<String,Object> adminDashboard(){return Map.of("students",users.count()-users.findAll().stream().filter(x->x.role.equals("ADMIN")).count(),"jobs",jobs.count(),"applications",applications.count(),"selected",applications.countByStatus("SELECTED"));}
 @GetMapping("/admin/jobs/all") List<Job> allJobs(){return jobs.findAll();}
 @GetMapping("/admin/students") List<?> students(){return users.findAll().stream().filter(x->x.role.equals("STUDENT")).map(x->Map.of("id",x.id,"fullName",x.fullName,"email",x.email,"profile",profiles.findByUserId(x.id).map(p->Map.of("college",Objects.toString(p.college,""),"department",Objects.toString(p.department,""),"cgpa",Objects.toString(p.cgpa,""),"resumeFilename",Objects.toString(p.resumeFilename,""))).orElse(Map.of()))).toList();}
 @GetMapping("/admin/students/{id}") Map<String,Object> student(@PathVariable Long id){var u=users.findById(id).filter(x->x.role.equals("STUDENT")).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var out=new LinkedHashMap<String,Object>(userView(u));out.put("profile",profileDetails(profiles.findByUserId(id).orElseThrow()));return out;}
 private Map<String,Object> profileDetails(StudentProfile p){var m=new LinkedHashMap<String,Object>();m.put("phone",p.phone);m.put("dateOfBirth",p.dateOfBirth);m.put("gender",p.gender);m.put("address",p.address);m.put("city",p.city);m.put("state",p.state);m.put("college",p.college);m.put("department",p.department);m.put("degree",p.degree);m.put("specialization",p.specialization);m.put("semester",p.semester);m.put("graduationYear",p.graduationYear);m.put("cgpa",p.cgpa);m.put("backlogs",p.backlogs);m.put("skills",p.skills);m.put("programmingLanguages",p.programmingLanguages);m.put("certifications",p.certifications);m.put("projects",p.projects);m.put("internships",p.internships);m.put("workExperience",p.workExperience);m.put("linkedinUrl",p.linkedinUrl);m.put("githubUrl",p.githubUrl);m.put("portfolioUrl",p.portfolioUrl);m.put("resumeFilename",p.resumeFilename);return m;}
 @GetMapping("/admin/students/{id}/resume") ResponseEntity<byte[]> studentResume(@PathVariable Long id){var p=profiles.findByUserId(id).orElseThrow();return resumeResponse(p);}
 @GetMapping("/admin/applications") List<?> allApplications(){return applications.findAll().stream().map(this::applicationView).toList();}
 @GetMapping("/admin/jobs/{jobId}/applications") List<?> jobApplications(@PathVariable Long jobId){return applications.findByJobIdOrderByAppliedAtDesc(jobId).stream().map(this::applicationView).toList();}
 @PatchMapping("/admin/applications/{id}/status") Map<String,Object> status(@PathVariable Long id,@RequestBody Map<String,String>b){String v=Objects.toString(b.get("status"),"").toUpperCase().replace(' ','_');if(!List.of("UNDER_REVIEW","SHORTLISTED","INTERVIEW_SCHEDULED","SELECTED","REJECTED").contains(v))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid application status");var x=applications.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));x.status=v;applications.save(x);var prefs=settings.findById(x.student.id).orElse(null);if(prefs==null||prefs.applicationUpdates){var n=new NotificationEntity();n.userId=x.student.id;n.title="Application update";n.message="Your application for "+x.job.title+" at "+x.job.companyName+" is now "+v.replace('_',' ').toLowerCase()+".";notifications.save(n);}return applicationView(x);}
 @PostMapping("/admin/jobs") ResponseEntity<?> createJob(@RequestBody @Valid JobInput b){var j=fromInput(b);return ResponseEntity.status(201).body(jobs.save(j));}
 @PutMapping("/admin/jobs/{id}") Job updateJob(@PathVariable Long id,@RequestBody @Valid JobInput b){var j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));copy(j,b);return jobs.save(j);}
 @DeleteMapping("/admin/jobs/{id}") ResponseEntity<?> deleteJob(@PathVariable Long id){var j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(applications.findByJobIdOrderByAppliedAtDesc(id).size()>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Jobs with applications cannot be deleted; close the job instead");jobs.delete(j);return ResponseEntity.noContent().build();}
 @PatchMapping("/admin/jobs/{id}/publish") Job publish(@PathVariable Long id){var j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));j.status="PUBLISHED";j.publishedAt=LocalDateTime.now();return jobs.save(j);}
 @PatchMapping("/admin/jobs/{id}/close") Job close(@PathVariable Long id){var j=jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));j.status="CLOSED";return jobs.save(j);}
 private Job fromInput(JobInput b){var j=new Job();copy(j,b);return j;}private void copy(Job j,JobInput b){j.companyName=b.companyName();j.title=b.title();j.location=b.location();j.employmentType=b.employmentType();j.salary=b.salary();j.description=b.description();j.responsibilities=b.responsibilities();j.qualifications=b.qualifications();j.skills=b.skills();j.minCgpa=b.minCgpa();j.departments=b.departments();j.deadline=b.deadline();j.selectionProcess=b.selectionProcess();j.additionalRequirements=b.additionalRequirements();}
}
